package career.assistant.application.ats;
import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class PublicAtsAdaptersTest {private final PublicAtsAdapters adapters=new PublicAtsAdapters();@Test void recognizesOnlyExactPublicFlows(){assertEquals("GREENHOUSE",adapters.resolve("https://boards.greenhouse.io/acme/jobs/12345").orElseThrow().name());assertEquals("LEVER",adapters.resolve("https://jobs.lever.co/acme/12345678-abcd-1234-abcd-123456789abc").orElseThrow().name());assertEquals("WORKABLE",adapters.resolve("https://apply.workable.com/acme/j/ABC123/").orElseThrow().name());assertTrue(adapters.resolve("https://evil.example/boards.greenhouse.io/acme/jobs/123").isEmpty());}@Test void unsupportedAndAuthenticatedFlowsAreManual(){assertTrue(PublicAtsAdapters.unsupportedReason("https://linkedin.com/jobs/1").contains("Authenticated"));assertTrue(PublicAtsAdapters.unsupportedReason("https://acme.myworkdayjobs.com/job/1").contains("Workday"));}}
